impl Solution{pub fn solve_sudoku(b:&mut Vec<Vec<char>>){fn f(b:&mut Vec<Vec<char>>,p:usize)->bool{if p==81{return true}let(i,j)=(p/9,p%9);if b[i][j]!='.'{return f(b,p+1)}for ch in b'1'..=b'9'{let c=ch as char;let mut ok=true;for x in 0..9{if b[i][x]==c||b[x][j]==c{ok=false;break}}if ok{let(r,c0)=(i/3*3,j/3*3);'z:for x in r..r+3{for y in c0..c0+3{if b[x][y]==c{ok=false;break'z}}}}if ok{b[i][j]=c;if f(b,p+1){return true}b[i][j]='.';}}false}f(b,0);}}
